# Step: find last approved Venmo payment request sent to Cory and send money back
cory_email = 'corwils@gmail.com'

# Fetch all approved payment requests we sent
approved_reqs = []
page_index = 0
while True:
    resp = apis.venmo.show_sent_payment_requests(access_token=venmo_token, status='approved', page_index=page_index, page_limit=20)
    print('page', page_index, 'count', len(resp))
    if not resp:
        break
    approved_reqs.extend(resp)
    page_index += 1

print('total approved sent requests', len(approved_reqs))

# Filter for receiver Cory
cory_reqs = [r for r in approved_reqs if r.get('receiver', {}).get('email') == cory_email or r.get('receiver', {}).get('name') == 'Cory']
print('cory_reqs count', len(cory_reqs))
# Print summary
for r in cory_reqs:
    print('id', r.get('payment_request_id'), 'amount', r.get('amount'), 'created_at', r.get('created_at'), 'approved_at', r.get('approved_at'), 'receiver', r.get('receiver'))

from datetime import datetime

def parse_dt(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return None

# choose last by created_at (fallback approved_at)
best = None
best_dt = None
for r in cory_reqs:
    dt = parse_dt(r.get('created_at'))
    if dt is None:
        dt = parse_dt(r.get('approved_at'))
    if dt is None:
        continue
    if best_dt is None or dt > best_dt:
        best_dt = dt
        best = r

print('selected_request', None if not best else {'payment_request_id': best.get('payment_request_id'), 'amount': best.get('amount'), 'created_at': best.get('created_at'), 'approved_at': best.get('approved_at'), 'receiver_email': best.get('receiver', {}).get('email')})

